(window.STORIES=window.STORIES||[]).push(
{"id": 1181, "siri": "Sirah-07", "no": 1, "tajuk": "Pelukan & Kata Penenang Khadijah RA Ketika Nabi SAW Pulang Menggigil Dari Gua Hira' (\"Allah Tidak Akan Mengecewakanmu!\")", "subtema": "Sokongan Emosi Isteri", "sumber": "Sahih al-Bukhari 3", "link": "https://sunnah.com/bukhari:3", "tema": "Kemesraan Suami Isteri", "hook": "Apabila seorang suami pulang ke rumah dalam keadaan takut, menggigil, dan tertekan dengan ujian besar di luar, siapakah manusia pertama yang dicari untuk menenangkan jiwanya?", "body": ["Detik pertama turunnya wahyu di Gua Hira' memperlihatkan kepada kita betapa agungnya peranan seorang isteri solehah bernama Khadijah binti Khuwailid RA!", "Ummul Mukminin Aisyah RA menceritakan bahawa selepas dipeluk tiga kali oleh Malaikat Jibril AS dengan wahyu Surah Al-'Alaq, Rasulullah SAW pulang ke rumah dalam keadaan jantung Baginda berdegup kencang dan tubuh Baginda menggigil ketakutan.", "Sebaik sahaja melangkah masuk ke rumah, Baginda terus berseru kepada isteri tercintanya: \"Zammiluni! Zammiluni! (Selimutkan aku! Selimutkan aku!)\"", "Khadijah RA tidak bertanya bertalu-talu atau menambah panik suaminya — beliau segera menyelimutkan dan menenangkan Rasulullah SAW sehinggalah hilang rasa takut Baginda!", "Apabila Rasulullah SAW menceritakan apa yang berlaku dan berkata: \"Sesungguhnya aku bimbang terhadap keselamatan diriku!\", dengarlah kata-kata penguat semangat paling indah daripada seorang isteri kepada suaminya:", "\"Sekali-kali tidak! Bergembiralah! Demi Allah, Allah tidak akan sesekali menghinakan atau mengecewakan dirimu selama-lamanya! Sesungguhnya engkau adalah seorang yang sentiasa menyambung silaturahim, memikul beban orang yang susah, membantu orang yang tiada harta, memuliakan tetamu, dan menolong orang yang ditimpa musibah di atas jalan kebenaran!\" (Sahih al-Bukhari 3).", "3 pengajaran besar daripada kisah sokongan emosi Khadijah RA ini:", "Apabila pasangan pulang dalam keadaan tertekan atau takut, berikan ketenangan fizikal dan emosi terlebih dahulu (\"selimutkan aku\") sebelum meminta penjelasan panjang.", "Khadijah RA menenangkan suaminya dengan mengingatkan rekod kebaikan akhlak suaminya sendiri, membuktikan bahawa orang yang baik di dalam rumah dan masyarakat tidak akan disia-siakan oleh Allah.", "Di sebalik ketabahan seorang lelaki yang memikul amanah besar di luar, ada seorang isteri yang menjadi benteng ketenangan pertama di dalam rumahnya.", "Apabila pasangan kita pulang dalam keadaan kecewa atau diuji masalah besar, adakah kata-kata pertama kita menguatkan semangatnya atau menambah bebannya?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1182, "siri": "Sirah-07", "no": 2, "tajuk": "Kesetiaan Cinta Rasulullah SAW Kepada Khadijah RA & Menghantar Hadiah Kepada Sahabat-Sahabat Khadijah Selepas Wafatnya", "subtema": "Kesetiaan Cinta Suami", "sumber": "Sahih Muslim 2435b & Bukhari 3818", "link": "https://sunnah.com/muslim:2435b", "tema": "Kemesraan Suami Isteri", "hook": "Ramai orang mudah melupakan pengorbanan pasangan apabila pasangan sudah tiada atau apabila sudah mengecapi kesenangan hidup.", "body": ["Tetapi lihatlah bagaimana Rasulullah SAW menjaga kesetiaan cinta dan kenangan terhadap Khadijah binti Khuwailid RA walaupun bertahun-tahun selepas Khadijah wafat!", "Ummul Mukminin Aisyah RA sendiri mengakui dengan jujur:", "\"Aku tidak pernah berasa cemburu kepada mana-mana isteri Rasulullah SAW sebagaimana cemburuku kepada Khadijah, padahal aku tidak pernah pun melihat wajahnya (kerana Khadijah telah wafat tiga tahun sebelum Nabi SAW mengahwiniku)!\"", "Mengapa Aisyah RA begitu cemburu kepada seorang wanita yang telah pun meninggal dunia?", "Aisyah RA menceritakan: \"Kerana Rasulullah SAW terlalu kerap menyebut-nyebut kebaikan Khadijah dan memujinya! Malah setiap kali Baginda menyembelih seekor kambing, Baginda pasti akan memotong bahagian-bahagian dagingnya lalu menghantarkannya sebagai hadiah kepada sahabat-sahabat baik Khadijah dahulu!\"", "Suatu hari, apabila Aisyah RA berkata dengan nada cemburu: \"Seolah-olah tiada wanita lain di dunia ini selain Khadijah!\", Rasulullah SAW menjawab dengan satu pengakuan cinta yang sangat tulus:", "\"Sesungguhnya dia itu begini dan begitu (banyak jasanya ketika orang lain mendustakanku), dan aku telah dikurniakan anak-anak daripadanya, serta sesungguhnya aku telah direzekikan oleh Allah perasaan cinta kepadanya!\" (Sahih Muslim 2435b & Sahih al-Bukhari 3818).", "3 pengajaran besar daripada kesetiaan cinta Rasulullah SAW kepada Khadijah RA:", "Lelaki yang mulia tidak akan sesekali melupakan pengorbanan isteri yang pernah bersamanya ketika waktu susah walaupun selepas dia mencapai puncak kejayaan.", "Rasulullah SAW menyatakan bahawa perasaan cinta yang halal di dalam hati suami terhadap isterinya adalah satu rezeki dan anugerah daripada Allah SWT (\"Inni ruziqtu hubbaha\").", "Sebaik-baik tanda kesetiaan kepada insan yang telah pergi ialah dengan menyambung silaturahim dan berbuat baik kepada rakan-rakan serta ahli keluarga yang pernah disayanginya semasa hidup.", "Sudahkah kita ucapkan terima kasih kepada pasangan kita hari ini atas segala pengorbanannya menemani kita sejak zaman susah dahulu?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1183, "siri": "Sirah-07", "no": 3, "tajuk": "Hati Rasulullah SAW Bergetar Mendengar Suara Adik Khadijah (Halah binti Khuwailid RA) Yang Persis Suara Khadijah", "subtema": "Kerinduan Kepada Isteri", "sumber": "Sahih al-Bukhari 3821", "link": "https://sunnah.com/bukhari:3821", "tema": "Kemesraan Suami Isteri", "hook": "Betapa dalamnya rindu Rasulullah SAW kepada arwah isteri tercinta Baginda, Khadijah RA, sehingga mendengar ketukan pintu dan suara yang mirip suara Khadijah sahaja sudah cukup menggetarkan hati Baginda!", "body": ["Ummul Mukminin Aisyah RA menceritakan satu peristiwa yang berlaku di Madinah — bertahun-tahun selepas kewafatan Khadijah RA di Makkah.", "Suatu hari, adik perempuan kandung kepada Khadijah RA yang bernama Halah binti Khuwailid RA datang berkunjung ke Madinah lalu meminta izin untuk masuk bertemu Rasulullah SAW.", "Gaya dan nada suara Halah binti Khuwailid ketika memberi salam dan meminta izin di luar pintu itu sama persis dengan gaya suara Khadijah RA ketika meminta izin masuk dahulu!", "Sebaik sahaja mendengar suara itu, Rasulullah SAW terus terkenangkan cara Khadijah meminta izin dahulu sehingga hati Baginda tersentak rindu dan bergetar lalu Baginda menyebut dengan penuh terharu:", "\"Allahumma Halah! (Ya Allah, ini suara Halah binti Khuwailid!)\" (Sahih al-Bukhari 3821).", "Melihat bagaimana wajah Rasulullah SAW berubah kerana rindukan Khadijah hanya dengan mendengar suara adiknya itu, Aisyah RA mengakui timbul rasa cemburu wanita di dalam hatinya kerana betapa utuhnya kedudukan Khadijah di dalam lubuk hati Rasulullah SAW!", "3 pengajaran besar daripada kisah Halah binti Khuwailid RA ini:", "Cinta sejati yang dibina atas dasar iman dan pengorbanan bersama selama 25 tahun tidak akan pudar dimakan waktu walaupun dipisahkan oleh kematian.", "Memuliakan ipar-duai dan ahli keluarga sebelah pasangan adalah sebahagian daripada bukti kasih sayang kita kepada pasangan sendiri.", "Rasulullah SAW tidak menyembunyikan perasaan rindu dan penghargaan Baginda kepada Khadijah RA, menunjukkan bahawa suami yang hebat adalah suami yang tahu menghargai kenangan bersama isterinya.", "Bagaimanakah layanan dan penghormatan kita terhadap adik-beradik serta ibu bapa mertua kita demi menggembirakan hati pasangan kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1184, "siri": "Sirah-07", "no": 4, "tajuk": "Lumba Lari Romantik Rasulullah SAW Bersama Aisyah RA (\"Ini Balasan Untuk Kemenanganmu Dahulu!\")", "subtema": "Riadah & Gurauan Suami Isteri", "sumber": "Sunan Abi Dawud 2578", "link": "https://sunnah.com/abudawud:2578", "tema": "Kemesraan Suami Isteri", "hook": "Siapa kata apabila sudah berkahwin dan memikul tanggungjawab besar agama, suami isteri tidak boleh bergurau senda dan bermain bersama seperti pasangan muda?", "body": ["Lihatlah betapa romantik dan sporting-nya Rasulullah SAW apabila bermusafir bersama isteri tercinta Baginda, Ummul Mukminin Aisyah RA!", "Aisyah RA menceritakan bahawa ketika beliau keluar dalam satu permusafiran bersama Rasulullah SAW (semasa Aisyah masih muda remaja dan bertubuh ringan), Rasulullah SAW berkata kepada para sahabat yang berada di dalam rombongan itu:", "\"Bergeraklah kamu semua berjalan ke hadapan terlebih dahulu!\"", "Mengapa Rasulullah SAW menyuruh para sahabat berjalan jauh ke hadapan dahulu?", "Supaya Baginda dapat meluangkan masa privasi berdua bersama isteri Baginda tanpa diperhatikan oleh orang ramai!", "Sebaik sahaja para sahabat sudah berada jauh di hadapan, Rasulullah SAW berpaling kepada Aisyah RA lalu mengajak isterinya: \"Marilah kita berlumba lari!\"", "Aisyah RA berkata: \"Maka aku pun berlari berlumba dengan Baginda, dan aku berjaya mengalahkan Baginda (kerana tubuhku masih ringan)!\"", "Bertahun-tahun kemudian, apabila tubuh Aisyah RA sudah agak berisi dan mereka keluar lagi dalam satu permusafiran, Rasulullah SAW sekali lagi menyuruh para sahabat berjalan ke hadapan lalu mengajak Aisyah berlumba lari buat kali kedua — kali ini Rasulullah SAW pula yang menang mendahului Aisyah, lalu Baginda ketawa tersenyum sambil mengusik isterinya:", "\"Hadzihi bi-tilkas sabqah! (Kemenangan hari ini adalah balasan seri untuk kemenanganmu dahulu!)\" (Sunan Abi Dawud 2578).", "3 pengajaran besar daripada kisah lumba lari Rasulullah SAW dan Aisyah RA:", "Suami isteri sangat memerlukan masa berkualiti berdua (quality time) dan aktiviti riadah bersama untuk mengekalkan kemesraan rumah tangga.", "Lihatlah betapa manisnya ingatan Rasulullah SAW — Baginda masih ingat perlumbaan pertama mereka bertahun-tahun sebelumnya dan menjadikannya bahan usikan yang menggembirakan hati isteri.", "Bermain dan bergurau senda dengan isteri bukanlah perkara sia-sia, malah ia adalah sunnah Nabi SAW yang menghidupkan suasana sakinah dan mawaddah.", "Bila kali terakhir kita keluar berjalan kaki, berjoging, atau beriadah santai berdua bersama pasangan kita sambil bergelak ketawa?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1185, "siri": "Sirah-07", "no": 5, "tajuk": "Romantika Minum Dari Tempat Bibir Yang Sama & Menggigit Daging Pada Bekas Mulut Aisyah RA", "subtema": "Kemesraan Di Meja Makan", "sumber": "Sahih Muslim 300", "link": "https://sunnah.com/muslim:300", "tema": "Kemesraan Suami Isteri", "hook": "Kalau nak belajar erti romantik yang sebenar dalam rumah tangga tanpa perlu berbelanja mewah, lihatlah apa yang dilakukan oleh Rasulullah SAW setiap kali makan dan minum di rumah bersama Aisyah RA!", "body": ["Pada zaman Jahiliyah (malah dalam sesetengah adat kaum lain ketika itu), apabila seorang isteri sedang berada dalam tempoh uzur (haid), mereka mengasingkan isteri mereka dan enggan makan atau minum bersama.", "Tetapi Rasulullah SAW meruntuhkan adat yang merendahkan wanita itu dengan menunjukkan kemuncak kasih sayang kepada isteri Baginda!", "Ummul Mukminin Aisyah RA menceritakan dengan penuh rasa bahagia:", "\"Aku pernah minum air daripada sebuah bekas minuman ketika aku sedang haid, kemudian aku menghulurkan bekas minuman itu kepada Rasulullah SAW — maka Baginda sengaja meletakkan mulut Baginda tepat pada tempat bekas bibirku minum tadi lalu Baginda meminumnya!\"", "Bukan itu sahaja! Aisyah RA menyambung lagi:", "\"Dan aku juga pernah menggigit daging daripada seketul tulang ('arq) ketika aku sedang haid, kemudian aku menghulurkannya kepada Rasulullah SAW — maka Baginda sengaja meletakkan mulut Baginda tepat pada tempat bekas gigitan mulutku tadi!\" (Sahih Muslim 300).", "Perhatikan ketelitian tindakan Rasulullah SAW — Baginda bukan sekadar berkongsi cawan yang sama, tetapi sengaja mencari di manakah letaknya bekas bibir isteri Baginda pada cawan itu!", "3 pengajaran besar daripada romantika makan minum Rasulullah SAW ini:", "Perbuatan kecil yang penuh perhatian (attentiveness) di meja makan seperti berkongsi cawan atau menyuap makanan memberikan isyarat cinta yang sangat besar kepada hati seorang isteri.", "Ketika isteri sedang berada dalam tempoh uzur bulanan dan emosinya mudah sensitif, waktu itulah suami patut menggandakan layanan mesra supaya isteri berasa dirinya tetap dihargai dan dicintai.", "Kebahagiaan rumah tangga tidak semestinya memerlukan hidangan hotel lima bintang; segelas air di rumah yang diminum dengan penuh kasih sayang sudah cukup mengikat dua hati.", "Pernah tak kita berkongsi segelas minuman atau menyuapkan makanan ke mulut pasangan kita di meja makan rumah sambil tersenyum?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1186, "siri": "Sirah-07", "no": 6, "tajuk": "Rasulullah SAW Menyandarkan Dagunya Di Bahu Aisyah RA Menonton Pertunjukan Habasyah Sehingga Aisyah Puas", "subtema": "Meraikan Jiwa Isteri Muda", "sumber": "Sahih al-Bukhari 5190", "link": "https://sunnah.com/bukhari:5190", "tema": "Kemesraan Suami Isteri", "hook": "Kadang-kadang minat seorang isteri berbeza dengan minat suami — isteri teringin melihat sesuatu pertunjukan yang halal, sedangkan suami mungkin tidak begitu berminat dengan pertunjukan tersebut.", "body": ["Apakah yang dilakukan oleh Rasulullah SAW apabila Aisyah RA teringin menonton pertunjukan permainan tombak orang-orang Habasyah di perkarangan Masjid Nabawi pada hari raya?", "Aisyah RA menceritakan bahawa pada hari raya itu, sekumpulan orang berkulit hitam dari Habasyah sedang bermain perisai dan lembing di dalam masjid sebagai hiburan hari raya.", "Rasulullah SAW bertanya dengan lembut kepada Aisyah: \"Wahai Aisyah, adakah engkau teringin melihat pertunjukan mereka?\" Aisyah menjawab: \"Ya!\"", "Maka Rasulullah SAW berdiri di muka pintu bilik Baginda (yang bersambung terus dengan ruang Masjid Nabawi), menghamparkan selendang Baginda sebagai tirai pelindung, lalu memanggil Aisyah berdiri rapat di belakang Baginda.", "Aisyah RA meletakkan dagunya di atas bahu Rasulullah SAW dan menyandarkan pipinya rapat ke pipi Rasulullah SAW sambil menonton pertunjukan tersebut!", "Walaupun Rasulullah SAW berdiri lama semata-mata menjadi tempat sandaran isterinya, Baginda tidak menyuruh Aisyah berhenti dengan cepat — setiap beberapa ketika Baginda hanya bertanya lembut: \"Sudah puaskah engkau wahai Aisyah?\"", "Dan apabila Aisyah berkata \"Belum lagi\" (kerana Aisyah sengaja ingin menguji betapa sayangnya Nabi SAW kepadanya), Rasulullah SAW tetap terus berdiri tenang menemaninya sehinggalah Aisyah sendiri yang bosan dan mengajak beredar! (Sahih al-Bukhari 5190).", "Malah di hujung hadis ini, Rasulullah SAW berpesan kepada para suami: \"Hargailah fitrah seorang gadis muda yang masih sukakan hiburan yang dibenarkan!\"", "3 pengajaran besar daripada kisah menonton pertunjukan Habasyah ini:", "Suami yang penyayang sanggup meluangkan masa dan berdiri lama menemani isterinya melakukan perkara halal yang diminati oleh isteri, walaupun suami sendiri tidak mempunyai hobi tersebut.", "Kemesraan fizikal (pipi bertemu pipi dan dagu di atas bahu suami) sambil melindungi aurat dan kehormatan isteri adalah contoh keseimbangan antara romantik dan sifat cemburu yang terpuji (ghirah).", "Rasulullah SAW mengajar para suami supaya memahami psikologi usia dan fitrah wanita, bukannya memaksa isteri menjadi kaku tanpa sebarang ruang kerehatan jiwa.", "Sanggupkah kita berdiri sabar menemani pasangan kita melakukan aktiviti kegemarannya semata-mata untuk melihat dia gembira?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1187, "siri": "Sirah-07", "no": 7, "tajuk": "Aktiviti Rasulullah SAW Di Rumah: Menjahit Baju, Menampal Kasut & Membantu Kerja Keluarga Hingga Azan", "subtema": "Suami Rajin Membantu Di Rumah", "sumber": "Sahih al-Bukhari 676", "link": "https://sunnah.com/bukhari:676", "tema": "Adab Rumah Tangga", "hook": "Di luar rumah, Baginda adalah Rasul utusan Allah, ketua negara, panglima tertinggi tentera, dan hakim agung seluruh umat Islam.", "body": ["Tetapi apabila melangkah masuk ke dalam pintu rumah, bagaimanakah sikap Rasulullah SAW terhadap kerja-kerja rumah tangga? Adakah Baginda duduk goyang kaki sambil mengarah isteri seperti raja?", "Seorang tabiin bernama Al-Aswad bin Yazid pernah bertanya terus kepada Ummul Mukminin Aisyah RA:", "\"Apakah yang biasa dilakukan oleh Rasulullah SAW apabila Baginda berada di dalam rumahnya?\"", "Dengarlah jawapan saksi utama yang tidur sebantal dengan Baginda, Aisyah RA:", "\"Baginda sentiasa berada dalam khidmat membantu urusan ahli keluarganya (fi mihnati ahlihi — membantu kerja-kerja rumah isterinya); dan apabila tiba waktu solat (terdengar laungan azan), maka Baginda pun keluar menuju ke masjid untuk bersolat!\" (Sahih al-Bukhari 676).", "Dalam riwayat lain, Aisyah RA memperincikan lagi kerja tangan yang dilakukan sendiri oleh Rasulullah SAW di rumah:", "\"Baginda adalah seorang manusia biasa seperti kamu semua; Baginda menjahit dan menampal sendiri pakaiannya yang koyak, memerah sendiri susu kambingnya, memperbaiki sendiri kasutnya, dan menguruskan keperluan dirinya sendiri!\"", "3 pengajaran besar daripada khidmat Rasulullah SAW di dalam rumah ini:", "Membantu isteri membuat kerja rumah, membasuh pinggan, mengemas, atau menguruskan pakaian sendiri bukanlah perkara yang menjatuhkan \"ego lelaki\", tetapi itulah sunnah tulen penghulu segala Rasul!", "Kemuliaan sebenar seorang lelaki diuji di dalam rumahnya sendiri — di luar ramai orang boleh berlakon baik di hadapan kawan, tetapi di dalam rumah terserlah akhlak sebenar.", "Keseimbangan hidup seorang Mukmin: di dalam rumah dia menjadi suami yang ringan tulang membantu keluarga, dan sebaik sahaja azan berkumandang dia bersegera menyahut panggilan Allah.", "Apakah satu kerja rumah yang boleh kita bantu ringankan daripada bahu isteri kita hari ini sebagai menghidupkan sunnah Rasulullah SAW?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1188, "siri": "Sirah-07", "no": 8, "tajuk": "Tangan Rasulullah SAW Tidak Pernah Sekali Pun Memukul Isteri Atau Pembantu Rumah Sepanjang Hidup Baginda", "subtema": "Anti-Keganasan Rumah Tangga", "sumber": "Sahih Muslim 2328a", "link": "https://sunnah.com/muslim:2328a", "tema": "Adab Rumah Tangga", "hook": "Kekuatan fizikal seorang lelaki dikurniakan oleh Allah SWT adalah untuk melindungi keluarganya, bukan sekali-kali untuk menyakiti atau menakut-nakutkan isteri dan anak-anak!", "body": ["Ummul Mukminin Aisyah RA memberikan satu kesaksian bersejarah yang wajib dipegang oleh setiap lelaki yang bergelar suami dan bapa:", "\"Rasulullah SAW tidak pernah sama sekali memukul sesuatu pun dengan tangan Baginda sepanjang hidupnya — tidak pernah sekali pun Baginda memukul seorang wanita (isteri), dan tidak pernah sekali pun Baginda memukul seorang khadam (pembantu rumah), melainkan ketika Baginda berjuang di medan jihad pada jalan Allah!\" (Sahih Muslim 2328a).", "Bayangkan: selama puluhan tahun berumah tangga dengan pelbagai latar belakang isteri dan kerenah pembantu, tidak pernah walau satu jari pun tangan Rasulullah SAW naik memukul isteri atau pembantu!", "Malah Aisyah RA menambah lagi dalam hadis yang sama:", "\"Dan tidak pernah sekali pun Baginda disakiti dalam urusan peribadinya lalu Baginda membalas dendam kerana dirinya sendiri, kecuali apabila batas larangan Allah dicabuli, maka Baginda bertindak semata-mata kerana Allah!\"", "3 pengajaran besar daripada rekod bersih tangan Rasulullah SAW ini:", "Keganasan rumah tangga (memukul, menampar, atau mendera isteri dan orang bawahan) adalah perbuatan yang bertentangan sama sekali dengan sunnah Rasulullah SAW.", "Lelaki yang paling gagah di medan perang seperti Rasulullah SAW adalah lelaki yang paling lembut tangannya apabila berada di hadapan isterinya di rumah.", "Mengawal kemarahan ketika berlaku perselisihan faham di dalam rumah tangga adalah tanda kematangan iman dan kewibawaan seorang ketua keluarga.", "Adakah tangan dan lidah kita di dalam rumah menjadi punca ketenangan buat isteri dan anak-anak, atau menjadi punca ketakutan mereka?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1189, "siri": "Sirah-07", "no": 9, "tajuk": "Kisah Pinggan Pecah Di Rumah Aisyah RA & Senyuman Tenang Nabi SAW (\"Ibu Kamu Sedang Cemburu\")", "subtema": "Seni Mengurus Cemburu Isteri", "sumber": "Sahih al-Bukhari 5225", "link": "https://sunnah.com/bukhari:5225", "tema": "Adab Rumah Tangga", "hook": "Bayangkan anda sedang menjamu sekumpulan kawan makan di ruang tamu rumah anda, tiba-tiba isteri anda yang sedang cemburu menolak pinggan makanan sehingga jatuh pecah berderai di hadapan semua tetamu!", "body": ["Kalau suami yang panas baran, pasti sudah berlaku pertengkaran besar di hadapan tetamu ketika itu juga!", "Tetapi lihatlah bagaimana tenang dan bijaksananya Rasulullah SAW menangani situasi itu di rumah Aisyah RA!", "Anas bin Malik RA menceritakan bahawa pada suatu hari, Rasulullah SAW sedang berada di rumah salah seorang isteri Baginda (Aisyah RA) bersama beberapa orang sahabat.", "Tiba-tiba seorang lagi isteri Rasulullah SAW menghantar seorang pembantu membawa semangkuk hidangan makanan yang sedap di dalam sebuah pinggan kepada Baginda.", "Apabila Aisyah RA melihat makanan kiriman madunya itu dibawa masuk pada hari gilirannya, timbul rasa cemburu yang kuat di dalam hatinya lalu beliau menepis tangan pembantu itu sehingga pinggan tersebut jatuh terhempas dan pecah terbelah dua di atas lantai!", "Apakah reaksi Rasulullah SAW di hadapan para sahabat?", "Tanpa sedikit pun menengking atau memalukan Aisyah RA, Rasulullah SAW tunduk merendahkan diri mengutip sendiri serpihan pinggan yang pecah itu, mengumpulkan semula makanan yang tumpah ke dalamnya, lalu bersabda kepada para sahabat dengan wajah yang tenang:", "\"Gharat ummukum! (Ibu kamu semua sedang cemburu!)\" — kemudian Baginda meminta diambilkan sebuah pinggan yang elok milik Aisyah untuk diserahkan sebagai ganti kepada isteri yang menghantar makanan tadi, manakala pinggan yang pecah itu ditinggalkan di rumah Aisyah! (Sahih al-Bukhari 5225).", "3 pengajaran besar daripada kisah pinggan pecah di rumah Aisyah RA ini:", "Rasulullah SAW memahami bahawa perasaan cemburu seorang isteri lahir kerana besarnya rasa cinta terhadap suaminya, maka Baginda menguruskannya dengan senyuman (\"Ibu kamu sedang cemburu\"), bukan dengan kemarahan.", "Walaupun Baginda memahami emosi Aisyah, Baginda tetap menegakkan keadilan dengan menggantikan pinggan yang pecah itu dengan pinggan yang baharu supaya tiada pihak yang teraniaya.", "Jangan sesekali memalukan atau memarahi isteri di hadapan orang luar apabila berlaku kesilapan emosi; lindungilah maruahnya dengan penuh hikmah.", "Apabila pasangan kita bertindak mengikut emosi kerana penat atau cemburu, mampukah kita menjadi air yang memadamkan api dengan tenang?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1190, "siri": "Sirah-07", "no": 10, "tajuk": "Kod Rahsia Rasulullah SAW Mengenal Pasti Bila Aisyah RA Redha Dan Bila Merajuk (\"Demi Tuhan Ibrahim\")", "subtema": "Peka Emosi & Rajuk Pasangan", "sumber": "Sahih al-Bukhari 5228", "link": "https://sunnah.com/bukhari:5228", "tema": "Adab Rumah Tangga", "hook": "Seorang suami yang benar-benar mencintai dan memberi perhatian kepada isterinya akan dapat mengesan perubahan emosi isterinya hanya daripada satu patah perkataan yang diucapkan!", "body": ["Ummul Mukminin Aisyah RA menceritakan satu perbualan yang sangat manis antara beliau dengan Rasulullah SAW.", "Suatu hari, Rasulullah SAW memandang Aisyah RA sambil tersenyum lalu berkata:", "\"Sesungguhnya aku benar-benar tahu bilakah masanya engkau sedang redha (gembira) denganku, dan bilakah masanya engkau sedang marah (merajuk) terhadapku!\"", "Aisyah RA bertanya dengan penuh rasa ingin tahu: \"Dari manakah engkau dapat mengetahui hal itu wahai Rasulullah?\"", "Rasulullah SAW menjawab dengan ketelitian seorang suami yang sangat peka:", "\"Apabila engkau sedang gembira dan redha denganku, setiap kali engkau bersumpah dalam percakapanmu engkau akan menyebut: 'Tidak, demi Tuhan Muhammad!' Tetapi apabila engkau sedang marah atau merajuk terhadapku, engkau akan bertukar menyebut: 'Tidak, demi Tuhan Ibrahim!'\"", "Mendengar bagaimana Rasulullah SAW perasan perubahan kecil pada kata-katanya itu, Aisyah RA tersenyum malu lalu memberikan satu jawapan cinta yang paling puitis dalam sejarah rumah tangga:", "\"Benar wahai Rasulullah! Demi Allah, aku hanya meninggalkan daripada menyebut namamu di bibirku sahaja (ketika merajuk), tetapi cintamu di dalam hatiku tidak pernah berubah sedikit pun!\" (Sahih al-Bukhari 5228).", "3 pengajaran besar daripada kisah \"Demi Tuhan Muhammad vs Demi Tuhan Ibrahim\" ini:", "Lihatlah betapa tajamnya pemerhatian Rasulullah SAW terhadap percakapan harian isterinya sehingga perubahan satu perkataan sahaja sudah cukup untuk Baginda memahami isi hati Aisyah.", "Lihat juga betapa beradabnya Aisyah RA ketika merajuk — walaupun sedang kecil hati dengan suami, beliau tidak pernah mengeluarkan kata-kata kesat atau menderhaka, malah hanya menukar sebutan kepada \"Tuhan Ibrahim\".", "Merajuk kecil dalam rumah tangga adalah lumrah kasih sayang; apabila disambut dengan usikan lembut oleh suami, ia sebenarnya mengeratkan lagi hubungan cinta.", "Sejauh mana kepekaan kita membaca perubahan nada suara atau raut wajah pasangan kita apabila dia sedang memendam rasa?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1191, "siri": "Sirah-07", "no": 11, "tajuk": "Rasulullah SAW Menghulurkan Lutut Baginda Sebagai Tangga Supaya Safiyyah RA Dapat Naik Ke Atas Unta", "subtema": "Memuliakan Isteri Di Khalayak", "sumber": "Sahih al-Bukhari 4211", "link": "https://sunnah.com/bukhari:4211", "tema": "Adab Rumah Tangga", "hook": "Dalam dunia moden, seorang lelaki dianggap gentleman jika dia membukakan pintu kereta untuk isterinya.", "body": ["Tetapi 1,400 tahun dahulu, di hadapan ribuan bala tentera Islam selepas pembukaan Khaibar, Rasulullah SAW menunjukkan satu tahap penghormatan seorang suami terhadap isterinya yang jauh lebih hebat daripada sekadar membuka pintu kereta!", "Anas bin Malik RA menceritakan peristiwa perjalanan pulang Rasulullah SAW selepas Baginda bernikah dengan Safiyyah binti Huyay RA (seorang wanita bangsawan yang sebelum itu kehilangan keluarganya dalam peperangan, lalu dimerdekakan dan dinikahi oleh Rasulullah SAW dengan penuh kemuliaan).", "Ketika hendak bertolak pulang menuju ke Madinah, Rasulullah SAW sendiri menghamparkan kain selendang Baginda di atas belakang unta untuk dijadikan alas tempat duduk yang lembut buat isterinya, Safiyyah RA.", "Kemudian apabila Safiyyah RA hendak memanjat naik ke atas unta yang tinggi itu, apakah yang dilakukan oleh pemimpin agung umat Islam itu di hadapan para sahabat?", "Anas bin Malik RA berkata: \"Aku melihat sendiri Rasulullah SAW duduk merendahkan diri di sisi unta Baginda, lalu Baginda menegakkan dan menghulurkan lutut Baginda supaya Safiyyah dapat meletakkan kakinya memijak di atas paha/lutut Rasulullah SAW untuk naik ke atas unta!\" (Sahih al-Bukhari 4211).", "Bayangkan: seorang Nabi dan ketua negara merendahkan lututnya ke tanah untuk dijadikan \"tangga\" tempat pijak kaki isterinya!", "3 pengajaran besar daripada tindakan Rasulullah SAW menghulurkan lutut buat Safiyyah RA:", "Merendahkan diri untuk memudahkan dan memuliakan isteri di khalayak ramai tidak pernah menjatuhkan martabat seorang suami, malah mengangkat darjatnya sebagai lelaki sejati.", "Safiyyah RA baru sahaja memeluk Islam dan masuk ke dalam masyarakat baharu; tindakan Rasulullah SAW memuliakannya di hadapan tentera memberikan mesej jelas bahawa Safiyyah adalah Ummul Mukminin yang wajib dihormati oleh semua.", "Perhatian kecil suami terhadap keselesaan fizikal isteri (menyediakan alas duduk dan membantu isteri menaiki kenderaan) adalah sunnah Nabawi yang sangat indah.", "Adakah kita masih mengekalkan adab membantu pasangan kita membawa barang berat atau membukakan pintu kenderaan walaupun sudah bertahun-tahun berkahwin?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1192, "siri": "Sirah-07", "no": 12, "tajuk": "Pesanan \"Berlemah-Lembutlah Dengan Kaca-Kaca (Kaum Wanita)!\" Ketika Rasulullah SAW Bermusafir Bersama Isteri", "subtema": "Kelembutan Terhadap Wanita", "sumber": "Sahih al-Bukhari 6210", "link": "https://sunnah.com/bukhari:6210", "tema": "Adab Rumah Tangga", "hook": "Pernahkah anda terfikir mengapa Rasulullah SAW mengumpamakan hati dan fizikal kaum wanita serta para isteri seperti bekas-bekas kaca (Al-Qawarir) yang perlu dijaga dengan penuh cermat?", "body": ["Anas bin Malik RA menceritakan bahawa dalam satu permusafiran jauh, isteri-isteri Rasulullah SAW dan kaum wanita berada di atas sekumpulan unta yang dipandu oleh seorang sahabat bersuara merdu bernama Anjasyah RA.", "Mengikut kebiasaan di padang pasir, apabila pemandu unta mengalunkan nyanyian rentak perjalanan (huda'), unta-unta akan menjadi bersemangat lalu mula berlari dengan langkah yang laju dan bergegar kuat!", "Apabila unta-unta itu mula bergerak laju kerana alunan suara Anjasyah, Rasulullah SAW bimbang gegaran kuat di atas belakang unta itu akan menyakitkan fizikal atau menakutkan hati para isteri dan kaum wanita yang sedang menunggang di atasnya.", "Maka Rasulullah SAW segera memanggil Anjasyah dengan satu metafora bahasa yang paling halus dan indah dalam kesusasteraan Arab:", "\"Ya Anjasyah! Ruwaidaka sauqaka bil-qawarir!\"", "Maksudnya: \"Wahai Anjasyah! Perlahan-lahanlah sedikit ketika engkau memandu unta yang sedang membawa bekas-bekas kaca (kaum wanita) itu!\" (Sahih al-Bukhari 6210).", "Ulama tabiin Abu Qilabah rahimahullah berkata: \"Demi Allah, Rasulullah SAW telah mengucapkan satu kalimat perumpamaan yang jika diucapkan oleh sesiapa pun selain Baginda tidak akan mampu menandingi keindahannya!\"", "3 pengajaran besar daripada perumpamaan \"Kaca-Kaca (Al-Qawarir)\" ini:", "Wanita diumpamakan seperti kristal atau kaca yang indah — ia sangat berharga dan cantik, tetapi mudah retak atau pecah jika dihentak dengan kata-kata kasar dan layanan yang keras.", "Walaupun dalam perkara memandu kenderaan ketika membawa isteri dan keluarga, seorang suami dituntut memandu dengan tenang dan cermat supaya isteri berasa selamat dan selesa.", "Apabila menegur isteri, gunakanlah bahasa yang lembut dan berhikmah kerana kaca yang sudah pecah sukar untuk dicantumkan kembali seperti asal.", "Adakah cara kita bercakap dan melayan isteri kita setiap hari menjaga hatinya seperti menjaga kristal berharga yang diamanahkan oleh Allah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1193, "siri": "Sirah-07", "no": 13, "tajuk": "Sembang Malam Kisah 11 Wanita Ummu Zar' & Sabda Nabi SAW: \"Aku Bagimu Seperti Abu Zar' Terhadap Ummu Zar'\"", "subtema": "Pillow Talk & Mendengar Isteri", "sumber": "Sahih al-Bukhari 5189", "link": "https://sunnah.com/bukhari:5189", "tema": "Adab Rumah Tangga", "hook": "Ramai isteri mengadu bahawa apabila mereka ingin bercerita panjang lebar kepada suami selepas seharian di rumah, suami hanya memandang skrin telefon sambil menjawab \"Hmm... ya...\" tanpa memberi tumpuan!", "body": ["Mari kita lihat bagaimana Rasulullah SAW mendengar cerita panjang daripada Aisyah RA tentang kisah 11 orang wanita tanpa memotong percakapannya walau sekali!", "Dalam satu hadis panjang di dalam Sahih al-Bukhari dan Sahih Muslim (dikenali sebagai Hadis Ummu Zar'), Aisyah RA duduk berbual mesra bersama Rasulullah SAW lalu menceritakan kisah sebelas orang wanita pada zaman dahulu yang berkumpul dan berjanji untuk menceritakan perihal perangai suami masing-masing tanpa menyembunyikan apa-apa (Sahih al-Bukhari 5189).", "Aisyah RA bercerita satu persatu daripada wanita pertama hingga wanita kesepuluh (ada yang mengadu suaminya kedekut, ada yang garang, ada yang malas, dan ada yang baik).", "Sehinggalah sampai kepada cerita wanita kesebelas bernama Ummu Zar', yang memuji suaminya Abu Zar' habis-habisan kerana suaminya menghadiahkannya perhiasan emas memenuhi telinga, menggembirakannya, tidak pernah mencelanya, dan memuliakan keluarganya — namun di hujung cerita, malangnya Abu Zar' telah menceraikan Ummu Zar' setelah bertemu wanita lain!", "Rasulullah SAW mendengar keseluruhan cerita panjang lebar 11 watak itu daripada awal hingga akhir dengan penuh minat dan senyuman!", "Dan sebaik sahaja Aisyah RA menamatkan ceritanya, Rasulullah SAW menutup perbualan malam itu dengan satu ayat romantik yang membuktikan Baginda mendengar setiap butir perkataan isterinya:", "\"Wahai Aisyah! Aku terhadap dirimu adalah sama seperti baiknya Abu Zar' terhadap Ummu Zar' (dalam menyayangi dan menggembirakanmu) — cuma bezanya, aku tidak akan sesekali menceraikanmu!\"", "3 pengajaran besar daripada kisah Pillow Talk Ummu Zar' ini:", "Mendengar cerita isteri dengan penuh perhatian (tanpa menyampuk atau memperlekehkan ceritanya) adalah salah satu nafkah emosi terbesar yang membahagiakan hati seorang wanita.", "Respons Rasulullah SAW di hujung cerita membuktikan Baginda bukan sekadar \"mendengar kosong\", tetapi menghayati jalan cerita isterinya dan menggunakannya untuk melafazkan janji kesetiaan cinta!", "Luangkanlah sekurang-kurangnya 15 hingga 20 minit setiap malam sebelum tidur untuk meletakkan telefon ke tepi dan berbual dari hati ke hati bersama pasangan.", "Malam ini sebelum tidur, mahukah kita letakkan telefon pintar ke tepi dan dengar cerita pasangan kita dengan sepenuh perhatian seperti sunnah Rasulullah SAW?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1194, "siri": "Sirah-07", "no": 14, "tajuk": "Rasulullah SAW Memanggil Aisyah RA Dengan Panggilan Manja \"Ya 'Aisy!\" Dan Menyampaikan Salam Jibril AS", "subtema": "Panggilan Manja & Penghormatan", "sumber": "Sahih al-Bukhari 3768", "link": "https://sunnah.com/bukhari:3768", "tema": "Kemesraan Suami Isteri", "hook": "Tahukah anda bahawa memanggil isteri dengan panggilan manja (tarkhim) yang sedap didengar adalah sunnah Rasulullah SAW yang diamalkan di dalam rumah Baginda?", "body": ["Abu Salamah meriwayatkan daripada Ummul Mukminin Aisyah RA bahawa Rasulullah SAW sering memanggil beliau dengan memendekkan hujung namanya secara manja:", "\"Ya 'Aisy! (Wahai 'Aisy sayang!)\" (dan dalam riwayat lain dengan panggilan \"Ya Humaira'\" — Wahai yang pipinya kemerah-merahan).", "Suatu hari, Rasulullah SAW memanggilnya dengan panggilan manja itu lalu menyampaikan satu berita yang paling menggembirakan hati seorang isteri solehah:", "\"Wahai 'Aisy! Ini Malaikat Jibril AS sedang berada di sini dan dia mengirimkan ucapan salam khusus untuk dirimu!\"", "Aisyah RA yang sangat pintar dan beradab terus menjawab dengan tenang:", "\"Wa 'alaihis salam wa rahmatullahi wa barakatuh (Dan ke atas Jibril juga kesejahteraan, rahmat Allah, dan keberkatan-Nya); wahai Rasulullah, sesungguhnya engkau dapat melihat apa yang tidak dapat aku lihat!\" (Sahih al-Bukhari 3768 & Sahih al-Bukhari 6201).", "Bayangkan betapa sejuknya hati seorang isteri apabila dipanggil dengan nama manja oleh suaminya, lalu diberitahu pula bahawa penghulu malaikat dari langit mengirimkan salam penghormatan kepadanya!", "3 pengajaran besar daripada kisah panggilan manja \"Ya 'Aisy\" ini:", "Panggilan yang lembut dan manja antara suami isteri di dalam rumah (bukan sekadar memanggil \"Oi\" atau nama penuh dengan nada keras) melembutkan hati dan menyuburkan rasa cinta setiap hari.", "Menyampaikan berita baik dan pujian orang yang mulia kepada isteri akan mengangkat semangat serta rasa dihargai di dalam jiwanya.", "Kemuliaan seorang wanita di sisi Allah dan para malaikat-Nya tercapai melalui ketaatan, ilmu, dan khidmat baktinya di dalam rumah tangga.", "Apakah panggilan paling manja dan doa yang paling disukai oleh pasangan kita apabila kita memanggil namanya di rumah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1195, "siri": "Sirah-07", "no": 15, "tajuk": "Mandi Bersama Dari Satu Bekas Air (Al-Faraq) & Gurauan Berebut Air (\"Tinggalkan Sedikit Untukku!\")", "subtema": "Kemesraan Dalam Kebersihan", "sumber": "Sahih al-Bukhari 250 & Muslim 321d", "link": "https://sunnah.com/bukhari:250", "tema": "Kemesraan Suami Isteri", "hook": "Islam adalah agama yang sangat indah dan syumul — sehinggakan kemesraan suami isteri ketika mandi membersihkan diri di dalam bilik air pun direkodkan sebagai sunnah yang berpahala!", "body": ["Ummul Mukminin Aisyah RA menceritakan bagaimana kemesraan beliau bersama Rasulullah SAW ketika mandi wajib (ghusl) di dalam rumah mereka:", "\"Aku biasa mandi bersama-sama dengan Rasulullah SAW daripada satu bekas air yang sama (yang dipanggil Al-Faraq).\"", "Bagaimanakah suasana ketika mereka berdua mandi daripada satu bekas air itu? Adakah ia kaku dan serius?", "Dalam riwayat Sahih Muslim, Aisyah RA menceritakan bahawa tangan mereka berdua saling berganti-ganti mencedok air di dalam bekas yang sama itu, dan Rasulullah SAW kadangkala sengaja mencedok dengan cepat untuk mengusik isterinya!", "Sehinggakan Aisyah RA berkata dengan manja kepada Baginda:", "\"Da' li! Da' li! (Tinggalkan sedikit air untukku! Tinggalkan sedikit air untukku!)\" (Sahih al-Bukhari 250 & Sahih Muslim 321d).", "Lihatlah betapa suci, mesra, dan bahagianya suasana rumah tangga Rasulullah SAW — daripada mihrab tahajjud sehinggalah ke gurauan berebut air mandi bersama isteri!", "3 pengajaran besar daripada hadis mandi bersama daripada satu bekas air ini:", "Kemesraan dan gurauan manja antara suami isteri yang sah adalah ibadah yang diredhai Allah SWT dan menjadi pengikat kasih sayang yang paling kuat.", "Dari sudut fiqh, hadis ini membuktikan bahawa air lebihan mandi suami atau isteri adalah suci lagi menyucikan dan harus bagi pasangan mandi bersama dari satu bekas.", "Jangan biarkan usia perkahwinan yang semakin meningkat menjadikan hubungan suami isteri hambar dan terlalu formal — kekalkanlah kemesraan dan usikan manja di dalam rumah.", "Adakah kita sentiasa berusaha menghidupkan semula kemesraan dan senyuman di dalam rumah tangga kita seperti zaman mula-mula bernikah dahulu?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1196, "siri": "Sirah-07", "no": 16, "tajuk": "Rasulullah SAW Beriktikaf Di Masjid Lalu Menghulurkan Kepala Ke Bilik Aisyah RA Untuk Disikat Rambutnya", "subtema": "Khidmat Mesra Suami Isteri", "sumber": "Sahih al-Bukhari 2028", "link": "https://sunnah.com/bukhari:2028", "tema": "Kemesraan Suami Isteri", "hook": "Walaupun ketika sedang beriktikaf sepenuh masa di dalam Masjid Nabawi pada bulan Ramadan, hubungan kasih sayang dan khidmat mesra antara Rasulullah SAW dengan isteri Baginda tidak pernah terputus!", "body": ["Bilik rumah Ummul Mukminin Aisyah RA terletak bersebelahan dan berkongsi dinding dengan ruang Masjid Nabawi.", "Aisyah RA menceritakan bagaimana kemesraan mereka berdua ketika Rasulullah SAW sedang menjalani ibadah iktikaf di dalam masjid:", "\"Apabila Rasulullah SAW sedang beriktikaf di dalam masjid, Baginda akan berdiri di tepi pintu sempadan masjid lalu menghulurkan kepala Baginda sahaja masuk ke dalam bilikku (sedangkan tubuh Baginda kekal berada di dalam ruang masjid supaya tidak membatalkan iktikaf)!\"", "Apakah yang dilakukan oleh Aisyah RA apabila Rasulullah SAW menghulurkan kepala Baginda ke dalam bilik itu?", "Aisyah RA berkata: \"Maka aku akan membasuh rambut Baginda, menyikat rambut Baginda dengan rapi, dan menyapukan minyak rambut pada kepala Baginda sedangkan aku ketika itu sedang berada dalam tempoh haid!\" (Sahih al-Bukhari 2028 & Sahih al-Bukhari 2029).", "Lihatlah betapa indahnya sentuhan seorang isteri yang menyikat dan merapikan rambut suaminya dengan penuh kasih sayang!", "3 pengajaran besar daripada kisah menyikat rambut ketika iktikaf ini:", "Kesibukan beribadah atau bekerja tidak menghalang seorang suami daripada tetap bermanja dan menerima sentuhan khidmat daripada isterinya.", "Perbuatan kecil seperti isteri menyikat rambut suami, memotong kuku, atau memakaikan wangian sebelum suami keluar ke masjid adalah pengikat hati yang sangat berkesan.", "Hadis ini juga menegaskan kemuliaan tubuh seorang wanita Muslimah — walaupun sedang uzur (haid), tangan dan sentuhannya adalah suci untuk berkhidmat kepada suaminya.", "Bila kali terakhir kita biarkan pasangan kita merapikan rambut atau pakaian kita sebelum kita keluar rumah sambil kita ucapkan terima kasih kepadanya?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1197, "siri": "Sirah-07", "no": 17, "tajuk": "Tiga Anak Bulan (Dua Bulan) Dapur Rumah Rasulullah SAW Tidak Berasap, Hanya Kurma Dan Air Tanpa Rungutan", "subtema": "Kesabaran Waktu Sempit", "sumber": "Sahih al-Bukhari 6459", "link": "https://sunnah.com/bukhari:6459", "tema": "Sabar & Pengorbanan Pasangan", "hook": "Ramai pasangan hari ini bergaduh besar sehingga hampir bercerai apabila diuji dengan kesempitan kewangan atau apabila barang dapur berkurang.", "body": ["Tetapi mari kita renungkan bagaimana keadaan dapur rumah manusia paling mulia di sisi Allah SWT — Rasulullah SAW — bersama isteri-isteri Baginda selama dua bulan berturut-turut!", "Anak saudara Aisyah RA yang bernama Urwah bin Az-Zubair menceritakan bahawa Ummul Mukminin Aisyah RA pernah berkata kepadanya dengan penuh keinsafan:", "\"Demi Allah wahai anak saudaraku! Kami (isteri-isteri Rasulullah SAW) pernah memandang anak bulan pertama, kemudian anak bulan kedua, kemudian anak bulan ketiga (tiga anak bulan dalam tempoh dua bulan penuh), dan sepanjang dua bulan itu tiada api pun yang dinyalakan di dalam rumah-rumah Rasulullah SAW (untuk memasak makanan atau roti)!\"", "Urwah yang terkejut bertanya: \"Wahai ibu saudaraku! Kalau dapur langsung tidak berasap selama dua bulan, apakah makanan yang menghidupkan kamu semua?\"", "Aisyah RA menjawab dengan tenang:", "\"Hanyalah Al-Aswadan (dua benda hitam) — iaitu buah kurma kering dan air sejuk sahaja! Cuma kadangkala Rasulullah SAW mempunyai jiran-jiran daripada kalangan Ansar yang memiliki unta tenusu, lalu mereka mengirimkan sedikit perahan susu kepada Baginda, maka Baginda pun memberi kami minum susu tersebut!\" (Sahih al-Bukhari 6459 & Sahih Muslim 2972a).", "3 pengajaran besar daripada kisah dapur rumah Rasulullah SAW ini:", "Kebahagiaan dan ketenangan sesebuah rumah tangga bukanlah terletak pada mewahnya perabot atau mahalnya hidangan setiap hari, tetapi pada sifat qana'ah (berasa cukup dan bersyukur) di dalam hati suami isteri.", "Walaupun hanya makan kurma dan air selama dua bulan, rumah tangga Rasulullah SAW kekal menjadi rumah tangga paling bahagia, paling romantik, dan paling tenang di dunia!", "Jangan jadikan ujian kesempitan rezeki sementara sebagai punca kita melukakan hati pasangan; bersabarlah bersama-sama kerana kesusahan yang dihadapi dengan redha akan diganti dengan kemuliaan abadi.", "Apabila rezeki keluarga kita sedang diuji sedikit sempit bulan ini, adakah kita masih mampu makan bersama pasangan dengan penuh rasa syukur dan senyuman?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1198, "siri": "Sirah-07", "no": 18, "tajuk": "\"Adakah Makanan Pagi Ini? Kalau Tiada Aku Berpuasa!\" & Tidak Pernah Mencela Masakan Isteri Seumur Hidup", "subtema": "Adab Suami Terhadap Makanan", "sumber": "Sahih Muslim 1154b & Bukhari 5409", "link": "https://sunnah.com/muslim:1154b", "tema": "Adab Rumah Tangga", "hook": "Bayangkan seorang suami pulang ke rumah dalam keadaan perut lapar pada waktu pagi, lalu bertanya kepada isterinya adakah sarapan sudah siap, dan isterinya menjawab: \"Tiada apa-apa makanan di dapur pagi ini.\"", "body": ["Kalau suami yang cerewet, pasti sudah muncung muka atau marah-marah, bukan?", "Tetapi lihatlah jawapan paling mulia dan paling menenangkan hati seorang isteri daripada lisan Rasulullah SAW!", "Ummul Mukminin Aisyah RA menceritakan:", "\"Pada suatu hari, Rasulullah SAW masuk menemui aku pada waktu pagi lalu bertanya dengan lembut: 'Wahai Aisyah, adakah pada kamu sebarang makanan untuk dimakan?'\"", "\"Kami menjawab: 'Tidak ada apa-apa wahai Rasulullah!'\"", "Apakah reaksi Rasulullah SAW sebaik sahaja mendengar tiada makanan di rumah?", "Baginda tidak mengeluh walau sepatah kata, tidak menyalahkan isterinya, malah terus tersenyum dan bersabda:", "\"Fa inni idzan sa'im! (Kalau begitu, hari ini aku berpuasa sunat sahaja!)\" (Sahih Muslim 1154b).", "Malah Abu Hurairah RA meriwayatkan satu lagi prinsip emas Rasulullah SAW di meja makan:", "\"Rasulullah SAW tidak pernah sekali pun mencela atau mengkritik sebarang makanan sepanjang hidup Baginda — jika Baginda berselera dengan makanan itu maka Baginda memakannya, dan jika Baginda tidak menggemarinya maka Baginda meninggalkannya dengan diam (tanpa komplen tawar, masin, atau tidak sedap)!\" (Sahih al-Bukhari 5409).", "3 pengajaran besar daripada adab Rasulullah SAW terhadap makanan di rumah:", "Jangan sesekali memalukan atau mengecilkan hati isteri yang penat memasak di dapur dengan mengkritik masakannya (\"terlalu masin\", \"tak sedap\") — pujilah usahanya atau diamlah dengan beradab.", "Apabila makanan belum sempat disediakan di rumah, respons Rasulullah SAW (\"Kalau begitu aku berpuasa\") terus menukar situasi yang boleh mencetuskan ketegangan menjadi pahala ibadah!", "Suami yang mudah diuruskan makan minumnya dan tidak cerewet adalah rahmat besar yang sangat meringankan beban emosi seorang isteri.", "Pernah tak kita memuji masakan isteri kita dengan ikhlas dan menghabiskannya sehingga dia rasa segala penat lelahnya di dapur sangat dihargai?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1199, "siri": "Sirah-07", "no": 19, "tajuk": "Kebijaksanaan Ummu Salamah RA Menasihati Rasulullah SAW Ketika Para Sahabat Terkedu Di Hudaibiyah", "subtema": "Isteri Sebagai Penasihat Suami", "sumber": "Sahih al-Bukhari 2731", "link": "https://sunnah.com/bukhari:2731", "tema": "Adab Rumah Tangga", "hook": "Jangan sesekali meremehkan pandangan dan buah fikiran seorang isteri — kerana dalam sejarah Islam, nasihat bijaksana seorang isteri kepada Rasulullah SAW telah menyelamatkan para sahabat daripada krisis besar pada hari Perjanjian Hudaibiyah!", "body": ["Selepas termeterainya Perjanjian Hudaibiyah yang mewajibkan umat Islam menangguhkan umrah ke tahun hadapan, hati para sahabat begitu sedih dan kecewa kerana tidak dapat masuk ke Makkah pada tahun itu.", "Rasulullah SAW keluar berdiri di hadapan para sahabat lalu bersabda sebanyak tiga kali: \"Wahai manusia, bangunlah kamu menyembelih haiwan korban kamu dan bercukurlah (untuk bertahallul)!\"", "Namun kerana kesedihan yang terlalu mendalam di hati mereka, tiada seorang pun daripada kalangan sahabat yang bingkas bangun melakukan arahan tersebut!", "Rasulullah SAW masuk ke dalam khemah menemui isteri tercinta Baginda yang ikut bersama dalam permusafiran itu, Ummul Mukminin Ummu Salamah RA, lalu Baginda meluahkan kesedihan tentang apa yang baru berlaku.", "Dengarlah nasihat psikologi kepemimpinan yang sangat bernas daripada seorang isteri solehah lagi pintar, Ummu Salamah RA:", "\"Wahai Nabiyullah! Adakah engkau mahu mereka semua melakukannya? Keluarlah engkau sekarang, dan janganlah engkau bercakap sepatah kata pun kepada sesiapa dalam kalangan mereka sehinggalah engkau sendiri menyembelih unta korbanmu dan engkau memanggil tukang cukurmu lalu mencukur rambutmu di hadapan mata mereka!\"", "Rasulullah SAW menerima pandangan isterinya itu, lalu Baginda keluar terus menyembelih unta Baginda dan mencukur rambut Baginda tanpa berkata apa-apa — sebaik sahaja para sahabat melihat tindakan praktikal Rasulullah SAW itu, mereka semua bingkas bangun berebut-rebut menyembelih korban dan mencukur rambut masing-masing! (Sahih al-Bukhari 2731).", "3 pengajaran besar daripada kebijaksanaan Ummu Salamah RA ini:", "Rasulullah SAW sendiri meminta dan menerima pandangan isteri Baginda dalam urusan besar negara dan umat, membuktikan betapa tingginya penghormatan Islam terhadap akal serta kebijaksanaan wanita.", "Ummu Salamah RA memahami psikologi manusia bahawa ketika orang ramai sedang dilanda emosi sedih, teladan perbuatan (action) jauh lebih berkesan menggerakkan mereka berbanding arahan lisan.", "Suami yang bijak menjadikan isterinya sebagai rakan mesyuarat (syura) dan tempat berbincang yang dipercayai dalam membuat keputusan keluarga.", "Adakah kita sentiasa mengajak pasangan kita duduk berbincang dan menghargai pandangannya sebelum membuat sesuatu keputusan penting dalam keluarga?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1200, "siri": "Sirah-07", "no": 20, "tajuk": "Kisah Madu, Bau \"Maghafir\" & Sunnah Rasulullah SAW Bersiwak Setiap Kali Melangkah Masuk Ke Dalam Rumah", "subtema": "Menjaga Kebersihan Untuk Isteri", "sumber": "Sahih al-Bukhari 4912 & Muslim 252", "link": "https://sunnah.com/bukhari:4912", "tema": "Adab Rumah Tangga", "hook": "Tahukah anda apakah perkara yang paling tidak disukai oleh Rasulullah SAW pada tubuh Baginda sendiri ketika berada bersama isteri-isteri Baginda, sehingga isteri-isterinya pernah menggunakan perkara itu untuk mengusik cemburu Baginda?", "body": ["Jawapannya ialah: Rasulullah SAW sangat benci jika mulut atau tubuh Baginda mengeluarkan sebarang bau yang kurang menyenangkan di hadapan isteri!", "Aisyah RA menceritakan bahawa pada suatu ketika, Rasulullah SAW gemar meminum air madu yang manis yang dihidangkan di rumah salah seorang isteri Baginda, Zainab binti Jahsy RA, sehingga Baginda duduk agak lama di situ.", "Kerana rasa cemburu wanita, Aisyah RA dan Hafsah RA berpakat secara rahsia bahawa sesiapa sahaja antara mereka berdua yang dimasuki oleh Rasulullah SAW selepas itu hendaklah berkata kepada Baginda: \"Wahai Rasulullah, adakah engkau telah memakan getah Maghafir? Kerana aku terhidu bau Maghafir (sejenis getah pokok yang manis tetapi berbau agak kuat) pada dirimu!\"", "Oleh kerana Rasulullah SAW seorang suami yang amat sensitif menjaga bau mulut dan kebersihan dirinya untuk isteri, sebaik sahaja ditegur kononnya berbau Maghafir, Baginda terus berkata: \"Tidak, aku hanya meminum madu di rumah Zainab, dan aku tidak akan meminumnya lagi selepas ini!\" sehinggalah turun ayat permulaan Surah At-Tahrim yang menegur dengan lembut peristiwa tersebut! (Sahih al-Bukhari 4912 & Sahih al-Bukhari 5267).", "Malah apabila tabiin Syuraih bin Hani' bertanya kepada Aisyah RA: \"Apakah perkara pertama yang dilakukan oleh Rasulullah SAW sebaik sahaja Baginda melangkah masuk ke dalam rumahnya?\", Aisyah RA menjawab dengan satu patah perkataan sahaja:", "\"Dengan bersiwak (menggosok dan membersihkan gigi Baginda terlebih dahulu sebelum menghampiri dan mencium isterinya)!\" (Sahih Muslim 252).", "3 pengajaran besar daripada kisah menjaga kebersihan mulut untuk isteri ini:", "Ramai suami hanya berhias dan memakai minyak wangi apabila hendak keluar bertemu orang lain di pejabat, tetapi apabila pulang ke rumah bertemu isteri, mereka membiarkan badan dan mulut berbau — sedangkan sunnah Nabi SAW ialah bersiwak sebaik sahaja masuk ke rumah!", "Betapa tingginya tahap kebersihan diri Rasulullah SAW sehingga tuduhan kecil ada bau getah pokok pada mulut Baginda sudah cukup membuatkan Baginda sangat prihatin.", "Menjaga penampilan yang kemas, bersih, dan harum untuk pasangan di dalam rumah adalah ibadah yang menyuburkan kasih sayang suami isteri.", "Setiap kali kita pulang ke rumah bertemu pasangan kita, adakah kita pastikan diri dan mulut kita bersih serta harum seperti sunnah Rasulullah SAW?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1201, "siri": "Sirah-07", "no": 21, "tajuk": "Abu Bakar RA Cuba Menegur Aisyah RA, Lalu Nabi SAW Melindunginya (\"Lihatlah Bagaimana Aku Menyelamatkanmu!\")", "subtema": "Melindungi Isteri & Jenaka Damai", "sumber": "Sunan Abi Dawud 4999", "link": "https://sunnah.com/abudawud:4999", "tema": "Adab Rumah Tangga", "hook": "Dalam mana-mana rumah tangga sekalipun, pasti akan ada hari di mana berlaku sedikit perbincangan hangat atau salah faham antara suami dan isteri.", "body": ["Tetapi lihatlah bagaimana Rasulullah SAW melindungi isterinya daripada dimarahi oleh bapa mertua sendiri, kemudian menukar suasana tegang itu menjadi bahan ketawa bersama isterinya!", "An-Nu'man bin Basyir RA menceritakan bahawa pada suatu hari, Abu Bakar As-Siddiq RA datang meminta izin untuk masuk ke rumah Rasulullah SAW.", "Dari luar pintu, Abu Bakar RA terdengar suara anak perempuannya sendiri, Aisyah RA, sedang bercakap dengan nada suara yang agak tinggi kepada Rasulullah SAW!", "Sebaik sahaja diizinkan masuk, Abu Bakar RA yang sangat menghormati Rasulullah SAW terus meluru ke arah Aisyah RA untuk menegur dan mencubit/memukul anaknya sambil berkata dengan tegas: \"Adakah patut aku melihat engkau meninggikan suaramu di hadapan Rasulullah SAW?!\"", "Apakah yang dilakukan oleh Rasulullah SAW? Adakah Baginda membiarkan bapa mertuanya memarahi Aisyah?", "Tidak! Rasulullah SAW segera berdiri menghalang di antara Abu Bakar dan Aisyah untuk melindungi isterinya sehingga Abu Bakar keluar dalam keadaan masih marah kepada Aisyah!", "Sebaik sahaja bapa mertuanya melangkah keluar dari pintu, Rasulullah SAW berpaling memandang Aisyah RA yang tadi sedang merajuk, lalu Baginda tersenyum mengusik isterinya:", "\"Tidakkah engkau lihat bagaimana aku telah menyelamatkan engkau daripada lelaki itu (ayahmu) tadi?!\" — kata-kata jenaka Rasulullah SAW itu terus mencairkan suasana sehingga mereka berdua kembali berdamai dan tersenyum!", "Beberapa hari kemudian, apabila Abu Bakar RA datang semula dan melihat Rasulullah SAW serta Aisyah RA sedang bergelak ketawa mesra, Abu Bakar RA tersenyum berkata: \"Wahai Rasulullah, masukkanlah aku ke dalam perdamaian kamu berdua sebagaimana kamu memasukkan aku ke dalam pertengkaran kamu berdua hari itu!\" Lalu Nabi SAW bersabda: \"Kami telah pun melakukannya! Kami telah pun melakukannya!\" (Sunan Abi Dawud 4999).", "3 pengajaran besar daripada kisah perdamaian rumah tangga ini:", "Walaupun sedang berselisih faham dengan isteri, seorang suami yang mulia tetap menjadi pelindung utama isterinya dan tidak membiarkan isterinya dikasari di hadapannya.", "Satu ayat jenaka yang lembut (\"Lihatlah bagaimana aku menyelamatkanmu tadi!\") mampu meruntuhkan tembok rajuk dan memulihkan kemesraan suami isteri dalam sekelip mata.", "Pertengkaran kecil dalam rumah tangga tidak seharusnya berlarutan berhari-hari; cepat-cepatlah berdamai dan kembali tersenyum seperti teladan Rasulullah SAW.", "Apabila berlaku sedikit salah faham di rumah, siapakah antara kita yang lebih cepat menghulurkan senyuman atau jenaka untuk menjernihkan keadaan?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1202, "siri": "Sirah-07", "no": 22, "tajuk": "Kisah Umar bin Al-Khattab RA & Bagaimana Isteri Sahabat Belajar Berbincang Mengikut Teladan Kelembutan Nabi SAW", "subtema": "Kesabaran Mendengar Pandangan Isteri", "sumber": "Sahih al-Bukhari 2468", "link": "https://sunnah.com/bukhari:2468", "tema": "Adab Rumah Tangga", "hook": "Tahukah anda bahawa kelembutan dan keterbukaan Rasulullah SAW mendengar pandangan isteri-isteri Baginda telah mengubah budaya seluruh kaum lelaki Quraisy yang dahulunya sangat garang dan tidak membenarkan isteri bersuara?", "body": ["Sahabat agung Umar bin Al-Khattab RA menceritakan sendiri perubahan besar itu di dalam Sahih al-Bukhari (Sahih al-Bukhari 2468 & Sahih al-Bukhari 5191):", "\"Kami kaum lelaki Quraisy semasa di Makkah dahulu adalah golongan yang sangat mendominasi isteri-isteri kami (isteri tidak berani membantah walau sepatah kata); tetapi apabila kami berhijrah ke Madinah, kami mendapati kaum Ansar adalah masyarakat yang sangat meraikan pandangan isteri-isteri mereka, maka wanita-wanita kami pun mula belajar daripada budaya wanita Ansar!\"", "Umar RA menceritakan: \"Pada suatu hari, aku sedang memikirkan satu urusan, tiba-tiba isteriku sendiri memberikan cadangan dan menjawab kata-kataku! Aku terkejut lalu berkata kepadanya: 'Adakah engkau berani menjawab kata-kataku?!'\"", "Apakah jawapan isteri Umar bin Al-Khattab RA?", "\"Mengapa engkau hairan aku menjawab dan berbincang denganmu wahai Umar? Demi Allah, sesungguhnya isteri-isteri Rasulullah SAW sendiri pun berbincang dan berhujah dengan Baginda, malah ada antara mereka yang merajuk dengan Baginda dari pagi sehingga ke malam (kerana sesuatu permintaan nafkah), namun Baginda tetap bersabar dengan mereka!\"", "Mendengar jawapan itu, Umar RA segera pergi menasihati anak perempuannya Hafsah RA (isteri Rasulullah SAW) supaya jangan menyusahkan hati Baginda dan jangan meminta sesuatu yang tiada pada Baginda, kerana kesabaran Rasulullah SAW melayan isteri-isteri Baginda adalah semata-mata kerana keluhuran akhlak Baginda!", "3 pengajaran besar daripada kisah Umar bin Al-Khattab RA ini:", "Rasulullah SAW membuka ruang komunikasi dua hala di dalam rumah tangga — isteri bukanlah robot yang tidak boleh menyuarakan perasaan atau pandangan di hadapan suami.", "Pada masa yang sama, nasihat Umar RA kepada anaknya Hafsah mengajar para isteri supaya tidak mengambil kesempatan atas kelembutan suami dengan menuntut perkara di luar kemampuan suami.", "Keseimbangan terbaik dalam rumah tangga ialah suami yang sabar dan lembut mendengar seperti Rasulullah SAW, digandingkan dengan isteri yang menghormati dan memahami kemampuan suami.", "Di dalam rumah tangga kita, adakah pasangan kita berasa bebas dan selamat untuk meluahkan pendapatnya tanpa takut ditempik?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1203, "siri": "Sirah-07", "no": 23, "tajuk": "Rumah Tangga Ali & Fatimah RA: Rasulullah SAW Mendamaikan Rajuk Menantu Di Masjid (\"Bangunlah Wahai Abu Turab!\")", "subtema": "Hikmah Bapa Mertua Mendamaikan", "sumber": "Sahih al-Bukhari 441", "link": "https://sunnah.com/bukhari:441", "tema": "Adab Rumah Tangga", "hook": "Bagaimanakah sikap terbaik seorang bapa mertua apabila mendengar anak perempuannya dan menantunya sedang merajuk atau berselisih faham kecil di rumah?", "body": ["Mari kita belajar daripada cara Rasulullah SAW mendamaikan rumah tangga puteri kesayangan Baginda, Fatimah Az-Zahra' RA, bersama menantu Baginda, Ali bin Abi Talib RA!", "Sahl bin Sa'ad RA menceritakan bahawa pada suatu hari, Rasulullah SAW datang menziarahi rumah Fatimah RA, namun Baginda tidak melihat kelibat Ali bin Abi Talib RA di dalam rumah.", "Rasulullah SAW bertanya dengan tenang: \"Di manakah anak bapa saudaramu (suamimu Ali)?\"", "Fatimah RA menjawab: \"Telah berlaku sedikit perselisihan faham antara aku dengannya tadi, lalu dia berkecil hati denganku dan keluar tanpa tidur tengah hari di sisiku.\"", "Adakah Rasulullah SAW terus memarahi Fatimah atau terus menyerang menantunya Ali tanpa usul periksa?", "Tidak sama sekali! Rasulullah SAW menyuruh seorang lelaki mencari di manakah Ali berada, lalu diberitahu bahawa Ali sedang baring di dalam Masjid Nabawi.", "Rasulullah SAW berjalan sendiri menuju ke masjid, lalu mendapati Ali sedang baring di atas lantai pasir masjid dalam keadaan kain selendangnya terjatuh dari bahunya sehingga belakang badannya disaluti debu tanah (turab).", "Rasulullah SAW menghampiri menantunya itu, lalu dengan tangan Baginda sendiri yang mulia, Baginda menyapu dan membersihkan debu tanah daripada belakang badan Ali sambil tersenyum memanggilnya dengan gelaran manja:", "\"Qum Aba Turab! Qum Aba Turab! (Bangunlah wahai Si Bapa Tanah! Bangunlah wahai Abu Turab!)\" (Sahih al-Bukhari 441 & Sahih al-Bukhari 6280).", "Sahl bin Sa'ad RA berkata: \"Demi Allah, tiada gelaran nama yang paling disukai dan paling menggembirakan hati Ali bin Abi Talib melebihi panggilan Abu Turab yang diberikan oleh Rasulullah SAW pada hari itu!\"", "3 pengajaran besar daripada cara Rasulullah SAW mendamaikan menantu dan anak ini:", "Ibu bapa mertua yang bijaksana tidak akan menjadi batu api yang membesarkan pergaduhan anak dan menantu, sebaliknya menjadi pendamai yang menyejukkan hati kedua-duanya.", "Lihatlah kematangan Ali bin Abi Talib RA — apabila berlaku sedikit ketegangan emosi di rumah, beliau tidak memaki hamun isterinya, sebaliknya keluar bertenang di dalam masjid.", "Sentuhan fizikal Rasulullah SAW menyapu pasir di belakang menantunya sambil memanggil dengan nama gurauan (Abu Turab) terus menghilangkan rasa rajuk Ali dan mengembalikannya ke pangkuan keluarganya dengan gembira.", "Bagi yang sudah bergelar ibu bapa atau mertua, adakah kehadiran kita menjadi penyejuk dan pendamai apabila anak-anak diuji salah faham rumah tangga?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1204, "siri": "Sirah-07", "no": 24, "tajuk": "Tangan Fatimah Az-Zahra' RA Melecet Mengisar Gandum & Hadiah Zikir Tasbih 33 Kali Sebelum Tidur", "subtema": "Ubat Kepenatan Isteri Di Rumah", "sumber": "Sahih al-Bukhari 5361", "link": "https://sunnah.com/bukhari:5361", "tema": "Adab Rumah Tangga", "hook": "Kepada semua para isteri dan ibu yang setiap hari berasa penat, sakit pinggang, dan lenguh seluruh badan menguruskan kerja rumah, memasak, dan menjaga anak-anak — hadis ini adalah ubat kekuatan khusus daripada Rasulullah SAW untuk anda!", "body": ["Ali bin Abi Talib RA menceritakan bahawa puteri kesayangan Rasulullah SAW sendiri, Fatimah Az-Zahra' RA, hidup dalam keadaan serba sederhana di peringkat awal perkahwinan mereka.", "Fatimah RA terpaksa memutar sendiri batu pengisar gandum dengan tangannya sehingga telapak tangannya melecet dan kasar, memikul sendiri bekas air dari perigi sehingga meninggalkan bekas tali di dadanya, dan menyapu rumah sehingga pakaiannya berdebu!", "Apabila terdengar berita bahawa Rasulullah SAW baru menerima beberapa orang tawanan pembantu, Fatimah RA pergi ke rumah Baginda untuk meminta seorang pembantu rumah, namun Baginda tiada di rumah ketika itu lalu Fatimah memaklumkan hajatnya kepada Aisyah RA.", "Pada malamnya, ketika Ali dan Fatimah RA sudah masuk berbaring di bawah selimut untuk tidur, tiba-tiba Rasulullah SAW datang sendiri ke rumah mereka!", "Ketika mereka berdua hendak bangun kerana hormatkan Baginda, Rasulullah SAW bersabda: \"Kekallah kamu berdua di tempat baring kamu!\" lalu Baginda duduk di antara mereka berdua sehingga Ali RA dapat merasai kesejukan tapak kaki Rasulullah SAW menyentuh dadanya.", "Kemudian Rasulullah SAW bersabda dengan penuh kasih sayang seorang ayah:", "\"Mahukah kamu berdua aku ajarkan sesuatu yang jauh lebih baik untuk kamu berdua daripada seorang pembantu rumah yang kamu minta itu? Apabila kamu berdua telah berbaring di tempat tidur kamu pada waktu malam, maka ucapkanlah Takbir (Allahu Akbar) 34 kali, Tasbih (Subhanallah) 33 kali, dan Tahmid (Alhamdulillah) 33 kali — sesungguhnya yang demikian itu jauh lebih baik bagi kamu berdua daripada seorang pembantu!\" (Sahih al-Bukhari 5361 & Sahih al-Bukhari 3113).", "Ali bin Abi Talib RA berkata: \"Demi Allah, sejak malam aku mendengar pesanan itu daripada Rasulullah SAW, aku tidak pernah sekali pun meninggalkan zikir itu sebelum tidur walau pada malam Perang Siffin!\"", "3 pengajaran besar daripada kisah Tasbih Fatimah sebelum tidur ini:", "Puteri kesayangan Nabi SAW sendiri pernah merasai tangan melecet kerana kerja rumah — maka setiap titik peluh isteri yang menguruskan rumah tangga adalah kemuliaan besar di sisi Allah.", "Ulama seperti Syeikhul Islam Ibnu Taimiyyah menjelaskan bahawa sesiapa yang mengamalkan zikir 33-33-34 (Tasbih Fatimah) ini sebelum tidur setiap malam, Allah akan mengurniakan kekuatan luar biasa pada tubuhnya keesokan pagi dan menghilangkan rasa lesu!", "Rasulullah SAW mendidik anak dan menantunya mendahulukan kepentingan orang miskin di luar (Ahli Suffah) berbanding keselesaan keluarga Baginda sendiri selagi mereka mampu berusaha.", "Malam ini sebaik sahaja meletakkan kepala di atas bantal bersama pasangan, jom kita amalkan zikir Tasbih Fatimah (33 Subhanallah, 33 Alhamdulillah, 34 Allahu Akbar) untuk cas semula tenaga tubuh dan jiwa kita!", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1205, "siri": "Sirah-07", "no": 25, "tajuk": "Doa Rahmat Rasulullah SAW Buat Suami Isteri Yang Saling Mengejutkan Pasangan Untuk Solat Malam (Tahajjud)", "subtema": "Cinta Suami Isteri Menuju Syurga", "sumber": "Sahih al-Bukhari 1127 & Abi Dawud 1308", "link": "https://sunnah.com/bukhari:1127", "tema": "Kemesraan Suami Isteri", "hook": "Cinta dunia akan terhenti di pintu kubur, tetapi cinta suami isteri yang saling memimpin tangan menuju syurga akan kekal abadi selama-lamanya!", "body": ["Tahukah anda bahawa Rasulullah SAW mendoakan Rahmat Khas daripada Allah SWT untuk pasangan suami isteri yang mempunyai satu tabiat mulia pada waktu malam?", "Pada suatu malam, Rasulullah SAW pergi mengetuk pintu rumah menantu dan puteri Baginda, Ali bin Abi Talib dan Fatimah RA, lalu bertanya dengan penuh kasih sayang:", "\"Tidakkah kamu berdua bangun untuk mengerjakan solat malam (Tahajjud)?\" (Sahih al-Bukhari 1127).", "Dan dalam hadis yang diriwayatkan oleh Abu Hurairah RA, Rasulullah SAW menggambarkan pemandangan paling romantik di sisi penduduk langit antara sepasang suami isteri:", "\"Semoga Allah mencurahkan rahmat-Nya ke atas seorang suami yang bangun pada waktu malam lalu dia mengerjakan solat Tahajjud, kemudian dia mengejutkan isterinya untuk turut bersolat; sekiranya isterinya masih berat kerana mengantuk, dia memercikkan sedikit air dengan lembut ke wajah isterinya!\"", "\"Dan semoga Allah mencurahkan rahmat-Nya ke atas seorang isteri yang bangun pada waktu malam lalu dia mengerjakan solat Tahajjud, kemudian dia mengejutkan suaminya untuk turut bersolat; sekiranya suaminya masih berat kerana mengantuk, dia memercikkan sedikit air dengan lembut ke wajah suaminya!\" (Sunan Abi Dawud 1308).", "Bayangkan betapa berkatnya sebuah rumah apabila pada waktu sepertiga malam, suami dan isteri berdiri bersebelahan di atas sejadah mendoakan keampunan keluarga mereka!", "3 pengajaran besar daripada hadis suami isteri bangun Tahajjud ini:", "Tanda cinta paling tinggi seorang suami kepada isterinya (dan isteri kepada suaminya) ialah dia tidak sanggup masuk ke dalam syurga seorang diri tanpa membawa pasangannya bersama.", "Mengejutkan pasangan untuk solat malam dan Subuh hendaklah dilakukan dengan penuh kelembutan dan gurauan kasih sayang (seperti renjisan air yang lembut), bukan dengan tengkingan yang merosakkan mood ibadah.", "Rumah tangga yang disinari dengan solat malam bersama-sama akan dikurniakan rahmat Allah yang memelihara mereka daripada perpecahan dan gangguan syaitan.", "Bila kali terakhir kita dan pasangan bangun 15 minit sebelum Subuh untuk solat sunat dua rakaat dan berdoa bersama-sama?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1206, "siri": "Sirah-07", "no": 26, "tajuk": "Rumah Tangga Az-Zubair & Asma' binti Abi Bakar RA: Pengorbanan Memikul Biji Kurma Di Atas Kepala", "subtema": "Kesetiaan Isteri Dari Bawah", "sumber": "Sahih al-Bukhari 5224", "link": "https://sunnah.com/bukhari:5224", "tema": "Sabar & Pengorbanan Pasangan", "hook": "Ramai wanita hari ini diuji bersuamikan lelaki yang baru hendak bermula membina hidup dari bawah — tiada harta mewah, tiada pembantu, dan serba kekurangan.", "body": ["Mari kita lihat kisah kesetiaan dan maruah luar biasa seorang isteri bangsawan, Asma' binti Abi Bakar As-Siddiq RA, ketika mula-mula berkahwin dengan sahabat mulia Az-Zubair bin Al-Awwam RA!", "Asma' binti Abi Bakar RA menceritakan sendiri permulaan rumah tangga mereka:", "\"Ketika Az-Zubair mengahwiniku, dia tidak memiliki sebarang tanah, tidak memiliki sebarang hamba pembantu, dan tidak memiliki apa-apa harta pun di atas muka bumi ini selain daripada seekor kuda dan seekor unta pengangkut air sahaja!\"", "Apakah yang dilakukan oleh Asma' RA, puteri kepada Abu Bakar As-Siddiq yang biasa hidup senang di Makkah dahulu?", "Asma' RA berkata: \"Akulah yang memberi makan rumput kepada kudanya, mencukupkan keperluannya, menguleni tepung, dan memikul sendiri guni biji-biji kurma di atas kepalaku dari tanah kebun Az-Zubair yang jaraknya kira-kira dua pertiga farsakh (hampir 3.5 kilometer berjalan kaki)!\"", "Pada suatu hari, sedang Asma' berjalan kaki memikul beban biji kurma di atas kepalanya, beliau berselisih dengan Rasulullah SAW bersama sekumpulan sahabat Ansar; kerana kasihan melihat Asma' berjalan memikul beban berat, Rasulullah SAW menghentikan unta Baginda (\"Ikh! Ikh!\") untuk menumpangkan Asma' di belakang.", "Namun kerana sifat malu seorang wanita yang tinggi dan kerana Asma' sangat menjaga perasaan cemburu (ghirah) suaminya Az-Zubair, Asma' memilih untuk terus berjalan kaki!", "Apabila Asma' pulang menceritakan hal itu kepada suaminya Az-Zubair, Az-Zubair RA yang sangat menghargai pengorbanan isterinya berkata dengan penuh terharu: \"Demi Allah! Engkau terpaksa memikul biji kurma yang berat di atas kepalamu itu jauh lebih berat di hatiku berbanding engkau menumpang unta Rasulullah SAW!\" — tidak lama kemudian, Allah membuka pintu rezeki yang melimpah-ruah sehingga Az-Zubair menjadi antara sahabat terkaya! (Sahih al-Bukhari 5224).", "3 pengajaran besar daripada kisah rumah tangga Az-Zubair dan Asma' RA:", "Kesabaran seorang isteri membantu suaminya yang sedang membina hidup dari bawah adalah pelaburan besar yang mengundang keberkatan rezeki keluarga pada masa hadapan.", "Seorang isteri yang bijak sangat menjaga maruah dirinya di luar rumah dan memahami perkara-perkara yang sensitif bagi hati suaminya.", "Lihatlah penghargaan Az-Zubair RA terhadap isterinya — beliau tidak menganggap kerja berat isterinya itu sebagai perkara biasa yang tidak perlu dihargai, malah berasa sangat kasihan dan terhutang budi kepada isterinya.", "Bagi para suami, sedarkah kita betapa banyaknya pengorbanan senyap yang dilakukan oleh isteri kita setiap hari demi menjimatkan dan membantu ekonomi keluarga?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1207, "siri": "Sirah-07", "no": 27, "tajuk": "Rumah Tangga Jabir bin Abdullah RA: Berkahwin Dengan Wanita Janda Demi Menjaga Adik-Adik Perempuan Yatim", "subtema": "Pengorbanan & Gurauan Pengantin", "sumber": "Sahih al-Bukhari 5367", "link": "https://sunnah.com/bukhari:5367", "tema": "Sabar & Pengorbanan Pasangan", "hook": "Kalau seorang pemuda bujang yang muda remaja hendak berkahwin buat kali pertama, kebiasaannya dia pasti akan memilih seorang gadis perawan yang sebaya dengannya.", "body": ["Tetapi sahabat muda Jabir bin Abdullah RA membuat satu keputusan perkahwinan yang mengejutkan Rasulullah SAW kerana satu pengorbanan keluarga yang sangat mulia!", "Dalam perjalanan pulang daripada satu peperangan bersama Rasulullah SAW, Baginda berbual mesra bertanya khabar kepada Jabir RA lalu mengetahui bahawa Jabir baru sahaja melangsungkan perkahwinan (Sahih al-Bukhari 5367 & Sahih al-Bukhari 4052).", "Rasulullah SAW bertanya dengan nada mesra seorang bapa dan sahabat:", "\"Wahai Jabir, adakah engkau berkahwin dengan seorang gadis perawan (bikran) atau seorang janda (thayyiban)?\"", "Jabir menjawab: \"Aku berkahwin dengan seorang wanita janda wahai Rasulullah.\"", "Rasulullah SAW bertanya dengan lembut: \"Mengapakah engkau tidak memilih seorang gadis perawan supaya engkau dapat bermain-main dan bergurau senda dengannya, dan dia juga dapat bermain-main serta bergurau senda denganmu?\"", "Dengarlah jawapan Jabir bin Abdullah RA yang mendedahkan betapa tingginya rasa tanggungjawab beliau sebagai abang sulung:", "\"Wahai Rasulullah! Sesungguhnya bapaku (Abdullah bin Amr bin Haram RA) telah gugur syahid dalam Perang Uhud dan meninggalkan tujuh (dalam riwayat lain sembilan) orang adik perempuanku yang masih kecil! Maka aku tidak suka membawa masuk seorang gadis muda yang sebaya dengan mereka (yang belum berpengalaman), sebaliknya aku memilih berkahwin dengan seorang wanita matang yang berpengalaman supaya dia dapat menyikat rambut adik-adik perempuanku dan menjaga urusan mereka seperti seorang ibu!\"", "Mendengar jawapan penuh pengorbanan itu, Rasulullah SAW sangat kagum lalu terus mendoakannya: \"Semoga Allah memberkati dirimu dan perkahwinanmu!\"", "3 pengajaran besar daripada kisah perkahwinan Jabir bin Abdullah RA:", "Soalan Rasulullah SAW (\"supaya engkau dapat bergurau senda dengannya dan dia bergurau senda denganmu\") membuktikan bahawa tujuan utama perkahwinan dalam Islam adalah kemesraan, gurauan kasih sayang, dan kebahagiaan dua hala.", "Kemuliaan hati Jabir RA yang sanggup mengetepikan kehendak peribadi demi memastikan adik-adik perempuannya yang yatim mendapat penjagaan terbaik daripada seorang isteri yang matang.", "Isteri Jabir RA juga sangat mulia kerana sanggup mengahwini pemuda yang memikul tanggungan ramai adik yatim dan menjadi \"ibu\" yang menyikat rambut mereka dengan penuh kasih sayang.", "Pernah tak kita membuat satu keputusan besar dalam hidup dengan mendahulukan kebajikan ibu bapa dan adik-beradik kita kerana mencari keredhaan Allah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1208, "siri": "Sirah-07", "no": 28, "tajuk": "Perkahwinan Abdurrahman bin Auf RA & Pesanan Nabi SAW: \"Adakanlah Walimah Walaupun Dengan Seekor Kambing\"", "subtema": "Keberkatan Walimah Sederhana", "sumber": "Sahih al-Bukhari 2048", "link": "https://sunnah.com/bukhari:2048", "tema": "Adab Rumah Tangga", "hook": "Bagaimanakah sebuah perkahwinan yang dimulakan dengan penuh maruah, usaha titik peluh sendiri, dan kenduri yang sederhana mengikut kemampuan boleh membuka pintu kekayaan jutawan yang melimpah-ruah?", "body": ["Lihatlah kisah perkahwinan sahabat agung Abdurrahman bin Auf RA sejurus selepas beliau berhijrah sehelai sepinggang ke Madinah! (Sahih al-Bukhari 2048 & Sahih al-Bukhari 5155).", "Apabila Rasulullah SAW mempersaudarakan Abdurrahman bin Auf RA dengan sahabat Ansar yang kaya, Sa'ad bin Ar-Rabi' RA, Sa'ad menawarkan separuh daripada seluruh hartanya untuk membantunya berkahwin.", "Namun Abdurrahman bin Auf RA menjaga maruah dirinya dengan mendoakan keberkatan buat Sa'ad sambil berkata: \"Tunjukkanlah sahaja kepadaku di manakah letaknya pasar tempat berniaga!\"", "Beliau pun pergi berniaga keju dan minyak sapi di Pasar Qainuqa' dengan penuh gigih.", "Beberapa hari kemudian, Abdurrahman bin Auf RA datang menghadap Rasulullah SAW dalam keadaan terdapat kesan warna kuning wangian pengantin (sufrah) pada pakaiannya!", "Rasulullah SAW tersenyum gembira melihat perubahan sahabatnya itu lalu bertanya: \"Apakah berita gembira ini wahai Abdurrahman?\"", "Abdurrahman menjawab: \"Wahai Rasulullah, aku baru sahaja berkahwin dengan seorang wanita daripada kalangan Ansar!\"", "Rasulullah SAW bertanya: \"Berapakah mahar (mas kahwin) yang engkau berikan kepadanya?\" Abdurrahman menjawab: \"Emas seberat sebiji kurma (nawah — kira-kira 3 ke 5 gram emas)!\"", "Lalu Rasulullah SAW mendoakan keberkatan rumah tangga dan hartanya serta berpesan:", "\"Barakallahu lak! Aulim walau bi-syatin! (Semoga Allah memberkatimu! Adakanlah kenduri kahwin / walimah walaupun hanya dengan menyembelih seekor kambing!)\"", "3 pengajaran besar daripada kisah perkahwinan Abdurrahman bin Auf RA ini:", "Lelaki yang bertanggungjawab tidak mengharapkan ihsan orang lain semata-mata untuk membina masjid, tetapi berusaha mencari rezeki halal dengan titik peluh sendiri di pasar sebelum meminang anak orang.", "Perkahwinan yang berkat tidak memerlukan hutang peribadi puluhan ribu ringgit untuk majlis yang membazir — sunnah Rasulullah SAW ialah mengadakan walimah mengikut kemampuan sebenar (\"walaupun dengan seekor kambing\").", "Doa sunnah pengantin (\"Barakallahu lak\") yang diucapkan oleh Rasulullah SAW kepada Abdurrahman bin Auf RA menjadikan rumah tangga dan perniagaannya diberkati luar biasa sehingga akhir hayat.", "Adakah kita mendidik anak-anak muda kita hari ini bahawa keberkatan perkahwinan terletak pada usaha yang halal dan kesederhanaan majlis mengikut sunnah Nabi SAW?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1209, "siri": "Sirah-07", "no": 29, "tajuk": "Rumah Tangga Abu Talhah & Ummu Sulaim RA: Menjaga Emosi Suami Yang Penat Pulang Ketika Anak Meninggal Dunia", "subtema": "Ketabahan Luar Biasa Seorang Isteri", "sumber": "Sahih Muslim 2144a", "link": "https://sunnah.com/muslim:2144a", "tema": "Sabar & Pengorbanan Pasangan", "hook": "Dalam senarai wanita paling tabah dan isteri paling bijaksana menjaga emosi suami dalam sejarah manusia, nama Ummu Sulaim binti Milhan RA berada di kedudukan yang sangat tinggi!", "body": ["Anas bin Malik RA menceritakan kisah benar yang berlaku di dalam rumah ibunya, Ummu Sulaim RA, bersama bapa tirinya, Abu Talhah Al-Ansari RA (Sahih Muslim 2144a & Sahih al-Bukhari 1301).", "Abu Talhah mempunyai seorang anak lelaki kecil yang sangat disayanginya yang sedang jatuh sakit.", "Pada suatu petang, ketika Abu Talhah keluar bekerja dan berada bersama Rasulullah SAW, anak kecil itu menghembuskan nafas terakhirnya di rumah!", "Apakah yang dilakukan oleh Ummu Sulaim RA?", "Beliau memandikan dan menutup jenazah anak kecil itu dengan tenang di satu bilik, lalu berpesan kepada ahli keluarganya: \"Jangan sesekali kamu memberitahu Abu Talhah tentang kematian anaknya sehinggalah aku sendiri yang memberitahunya!\"", "Mengapa? Kerana Ummu Sulaim tahu suaminya sedang berpuasa dan pulang dalam keadaan letih — beliau tidak mahu mengejutkan suaminya di muka pintu dalam keadaan perut kosong dan penat!", "Apabila Abu Talhah pulang pada waktu malam dan bertanya: \"Bagaimana keadaan anakku malam ini?\", Ummu Sulaim menjawab dengan kalimat dua maksud yang benar tetapi menenangkan: \"Dia malam ini berada dalam keadaan paling tenang yang pernah dia alami sejak sakitnya!\"", "Kemudian Ummu Sulaim menghidangkan makan malam untuk suaminya, berhias cantik untuk suaminya, dan melayani suaminya dengan penuh kasih sayang; sehinggalah apabila suaminya sudah kenyang dan tenang di hujung malam, barulah Ummu Sulaim bertanya dengan lembut:", "\"Wahai Abu Talhah, apakah pandanganmu jika satu kaum meminjamkan sesuatu barang kepada sebuah keluarga, kemudian pemilik asal itu meminta semula pinjamannya, patutkah keluarga itu menghalangnya?\" Abu Talhah menjawab: \"Tidak patut!\" Maka Ummu Sulaim pun berkata: \"Kalau begitu, bersabarlah dan harapkanlah pahala atas pemergian anakmu!\"", "Keesokan paginya, apabila Rasulullah SAW mendengar kisah ketabahan luar biasa isteri Abu Talhah itu, Baginda mendoakan keberkatan malam mereka berdua sehingga lahirlah zuriat yang melahirkan 10 orang ulama Al-Quran!", "3 pengajaran besar daripada kisah rumah tangga Abu Talhah dan Ummu Sulaim RA:", "Masa dan cara (timing and delivery) ketika menyampaikan berita berat atau masalah kepada pasangan yang baru pulang penat adalah seni komunikasi rumah tangga yang sangat penting.", "Keimanan yang mendalam kepada konsep bahawa anak dan harta adalah \"pinjaman Allah\" memberikan kekuatan luar biasa kepada seorang ibu untuk kekal tenang di saat ujian terbesar.", "Ketenangan seorang isteri di dalam rumah ketika berlakunya krisis menjadi tiang seri yang menyelamatkan emosi seluruh keluarga.", "Apabila ada berita yang merunsingkan di rumah, adakah kita bijak memilih waktu yang sesuai selepas pasangan kita berehat dan makan sebelum kita menyampaikannya?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1210, "siri": "Sirah-07", "no": 30, "tajuk": "Detik Terakhir Rasulullah SAW Di Atas Dada Aisyah RA & Wasiat \"Sebaik-Baik Kamu Ialah Yang Paling Baik Terhadap Isterinya\"", "subtema": "Penutup Cinta Agung Hingga Akhir Hayat", "sumber": "Sahih al-Bukhari 4449 & Tirmidhi 3895", "link": "https://sunnah.com/bukhari:4449", "tema": "Kemesraan Suami Isteri", "hook": "Sebagai penutup kepada 30 cerita rumah tangga Set 7 ini, mari kita saksikan di manakah manusia paling agung di sisi Allah SWT menghembuskan nafas Baginda yang terakhir di dunia ini!", "body": ["Bukan di atas singgahsana emas, bukan di tengah medan perang, tetapi di atas pangkuan dada isteri tercinta Baginda, Ummul Mukminin Aisyah RA!", "Aisyah RA menceritakan detik-detik kewafatan Rasulullah SAW dengan penuh rasa syukur dan rindu yang mendalam (Sahih al-Bukhari 4449):", "\"Sesungguhnya antara nikmat kurniaan Allah yang paling besar ke atas diriku ialah Rasulullah SAW wafat di dalam rumahku, pada hari giliranku, dan ketika kepala serta belakang Baginda sedang bersandar tepat di antara dada dan leherku!\"", "\"Dan Allah telah menyatukan air liurku dengan air liur Baginda pada saat-saat terakhir hidupnya di dunia!\"", "Bagaimanakah itu berlaku?", "Ketika Rasulullah SAW sedang bersandar lemah di dada Aisyah RA, abang Aisyah (Abdurrahman bin Abi Bakar RA) masuk sambil memegang sebatang kayu siwak (pembersih gigi).", "Aisyah RA yang sangat mengenali tabiat suaminya perasan mata Rasulullah SAW memandang ke arah kayu siwak itu, lalu Aisyah bertanya dengan penuh kasih sayang: \"Wahai Rasulullah, adakah engkau mahu aku ambilkan kayu siwak itu untukmu?\" Baginda menganggukkan kepala.", "Oleh kerana kayu siwak itu masih keras, Aisyah bertanya lagi: \"Mahukah aku lembutkan hujungnya untukmu?\" Baginda mengangguk lagi — maka Aisyah RA mengunyah hujung kayu siwak itu dengan giginya sendiri untuk melembutkannya, lalu memberikannya kepada Rasulullah SAW sehingga Baginda dapat bersiwak dengan sempurna sebelum mengangkat jari telunjuk Baginda menyebut: \"Allahummar Rafiqal A'la (Ya Allah, bersama Kekasih Yang Maha Tinggi)!\"", "Dan ingatlah kayu ukur kejayaan sebenar seorang lelaki yang ditinggalkan oleh Rasulullah SAW buat kita semua:", "\"Khairukum khairukum li-ahlihi, wa ana khairukum li-ahli!\"", "Maksudnya: \"Sebaik-baik kamu ialah orang yang paling baik terhadap ahli keluarganya (isterinya), dan akulah orang yang paling baik dalam kalangan kamu terhadap ahli keluargaku!\" (Jami' at-Tirmidhi 3895).", "3 pengajaran besar daripada detik terakhir rumah tangga Rasulullah SAW ini:", "Sijil kemuliaan sebenar seorang lelaki Muslim bukanlah apa yang dipuji oleh orang ramai di luar, tetapi pengakuan isterinya sendiri bahawa suaminya adalah insan yang paling baik terhadapnya di dalam rumah.", "Kasih sayang seorang isteri yang memahami kehendak suaminya hanya melalui pandangan mata (tanpa perlu suami bersuara ketika sakit) adalah kemuncak keserasian jiwa suami isteri.", "Semoga Allah SWT mengurniakan kepada rumah tangga kita semua sakinah, mawaddah, dan rahmah di dunia sehingga kita dipertemukan semula bersama pasangan dan keluarga kita di dalam syurga Firdaus yang abadi!", "Jika hari ini pasangan kita ditanya oleh Allah SWT tentang layanan kita terhadapnya sepanjang perkahwinan ini, adakah dia akan tersenyum menjadi saksi kebaikan kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]}
);
